import{_ as o,o as t,c as e,y as l}from"./chunks/framework.CNTkXYA8.js";const d=JSON.parse('{"title":"【OI】时间复杂度","description":"","frontmatter":{"title":"【OI】时间复杂度","date":"2020-10-23T19:16:00.000Z"},"headers":[],"relativePath":"blog/post-13865757.md","filePath":"source/old_posts/post-13865757.md"}'),a={name:"blog/post-13865757.md"};function n(s,p,_,r,c,i){return t(),e("div",null,[...p[0]||(p[0]=[l("<p>学了高数之后，以前一直理解得模模糊糊的时间复杂度明白了不少。</p><p>我们通常说的时间复杂度指的是大O，中文名称是渐进时间复杂度，为什么叫渐进时间复杂度，</p><p>原因就是其描述的是算法的耗时随着数据规模的变动的变化趋势。</p><p>所谓变化趋势，大约可以类比为导数。但是又有些不一样，</p><p>我们的大O在计算的时候并不需要把系数带进来，而是直接计算。</p><p>而显然，代码执行时间和代码执行次数成正比，即T(n)=kf(n),f(n)为代码执行次数，</p><p>所以一层循环是O(n)，两层是O(n^2)。</p><p>而log是怎么来的呢？对于对数，我们有一个换底公式，即</p><p>loga(b) + logc(a) = logc(b)，</p><p>考察代码</p><p>for(int i = 1; i &lt;= 255; i *= 2) k ++;</p><p>显然可以看出它执行了log2(255)次，</p><p>而如果2变为三，有log3(255)次</p><p>但是log3(255) = log3(2) + log2(255)</p><p>因为log3(2)是定值，根据前文的推导，</p><p>可以利用数学归纳法得到这样的算法的时间复杂度是O(log10(n))，简写为O(logn)</p>",16)])])}const f=o(a,[["render",n]]);export{d as __pageData,f as default};
